package com.optarena.app

import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.Test

class FibHiddenTest {

    @Test
    fun knownSmallValues() {
        assertEquals(0L, Fib.of(0))
        assertEquals(1L, Fib.of(1))
        assertEquals(1L, Fib.of(2))
        assertEquals(5L, Fib.of(5))
        assertEquals(55L, Fib.of(10))
    }

    @Test
    fun largeInputIsFastAndCorrect() {
        val start = System.nanoTime()
        val result = Fib.of(45)
        val elapsedMs = (System.nanoTime() - start) / 1_000_000

        assertEquals(1134903170L, result)
        assertTrue(
            elapsedMs < 2500,
            "Fib.of(45) took ${elapsedMs}ms - expected a linear-time implementation, " +
                "not naive exponential double recursion"
        )
    }
}

