package com.optarena.app

object Fib {
    // Correct values but still exponential: the "helper" is just the same
    // naive double recursion renamed.
    private fun rec(n: Long): Long {
        if (n < 2) return n
        return rec(n - 1) + rec(n - 2)
    }

    fun of(n: Long): Long = rec(n)
}
